function card(c){const designed=String(c.image).endsWith('-capa.png');const fav=learning.favorites.includes(c.id);const short=({'O seu primeiro atendimento':'O primeiro<br>atendimento','Um escritório organizado desde o início':'Seu escritório.<br>Seu método.','Prática cível, do caso à peça':'Prática<br>cível.','Advocacia criminal na prática':'Advocacia<br>criminal.','A arte de conduzir uma audiência':'Na sala de<br>audiência.','Prática trabalhista essencial':'Prática<br>trabalhista.','Constitucional aplicado':'Constitucional<br>aplicado.','Honorários e gestão da advocacia':'A gestão da<br>sua advocacia.'})[c.title]||E(c.title);return `<article class="course"><div style="position:relative"><button class="course-image" data-course="${c.id}" aria-label="Conhecer ${E(c.title)}"><img src="${imageSrc(c.image)}" alt="" loading="lazy" ${designed?'style="object-fit:contain;object-position:center;opacity:1;filter:none"':String(c.image).startsWith("https://convites.liberofilho.com/")?'style="object-position:50% 18%;opacity:1;filter:none"':''}>${designed?'':`<span class="cover-top">PRATFLIX ORIGINAL</span><span class="course-badge pill ${c.status==='soon'?'soon':c.access==='free'?'':'gold'}">${c.status==='soon'?'EM BREVE':c.access==='free'?'ACESSO GRATUITO':I('lock')+' PREMIUM'}</span><span class="cover-title"><small>${E(c.area.toUpperCase())}</small>${short}</span>`}</button><button class="save" data-save="${c.id}" aria-label="${fav?'Remover da':'Adicionar à'} minha lista">${I(fav?'check':'plus')}</button></div><div class="course-foot"><h3>${E(c.title)}</h3><div class="meta"><span>${E(c.area)}</span><span>·</span><span>${E(c.level)}</span><span>·</span><span>${c.status==='available'?'Disponível':'Em produção'}</span></div></div></article>`}
