function title(k,h,p){return `<div class="page-title"><span class="eyebrow">${k}</span><h1>${h}</h1><p>${p}</p></div>`}
function catalog(saved=false){let list=courses.filter(c=>(canAdmin()||c.status!=='draft')&&(!saved||learning.favorites.includes(c.id))&&(area==='Todas'||c.area===area||area==='Gratuitos'&&c.access==='free')&&(!query||(c.title+' '+c.area+' '+c.subtitle).toLowerCase().includes(query.toLowerCase())));return title(saved?'SUA CURADORIA':'EXPLORE. DESCUBRA. APRENDA.',saved?'Minha lista':'Conhecimento para o seu próximo passo',saved?'Os conteúdos que você escolheu para voltar depois.':'Explore por área, encontre seu ponto de partida e construa uma prática com mais método.')+`<div class="toolbar"><input id="catalog-search" placeholder="Buscar cursos, temas e áreas" aria-label="Buscar cursos" value="${E(query)}"><span class="tagline">${list.length} conteúdos</span></div><div class="areas">${['Todas','Gratuitos',...new Set(courses.filter(c=>canAdmin()||c.status!=='draft').map(c=>c.area))].map(a=>`<button class="chip ${area===a?'active':''}" data-filter="${a}">${a}</button>`).join('')}</div><div class="grid" id="catalog-grid">${list.length?list.map(card).join(''):empty('Ainda não há conteúdos aqui',saved?'Toque no símbolo + de uma capa para guardar um conteúdo.':'Experimente buscar por outra área ou limpar os filtros.',saved?'catalog':'clear-search',saved?'Explorar catálogo':'Limpar filtros')}</div>`}
