async function route(p,changeHash=true){toolkit.cancel();journey.cancel();communityRequest++;const navigation=++navigationSeq;page=p||'home';if(page==='home'&&user&&(tier()==='free'||preview))page='today';await stopVideoTracking();if(navigation!==navigationSeq)return;if(page==='home'&&user)await loadPlaybackHistory();if(navigation!==navigationSeq)return;if(changeHash)history.replaceState(null,'','#'+page);document.body.classList.remove('nav-open');window.scrollTo({top:0,behavior:'instant'});if(page==='tools'||page==='tools-admin'||page.startsWith('tool/')){await toolkit.render(page);return}if(['today','welcome','journey','journey-admin'].includes(page)||page.startsWith('activity/')){await journey.render(page);return}if(page==='auth'||page==='signup'){shell(home());auth(page==='signup'?'signup':'login');return}if(page==='community'){loadCommunity();return}if(page==='admin'){if(!canAdmin()){shell(empty('Acesso reservado','Entre com a conta administradora para gerenciar o PratFlix.','auth','Entrar'));return}loadAdmin();return}const views={home,catalog:()=>catalog(),saved:()=>user?catalog(true):empty('Guarde seus próximos passos','Entre para criar sua lista pessoal.','auth','Entrar'),paths:pathsPage,library:libraryPage,models:()=>pratica.models(),tips:tipsPage,progress:progressPage,premium:premiumPage,account:accountPage};if(!views[page]){page='home'}shell((views[page]||home)())}
