function close(){ $('#modal-root').innerHTML='';document.body.style.overflow='';lastModalFocus?.focus?.() }
async function saveLearning(){if(!user||preview)return;const payload={user_id:user.id,favorites:learning.favorites,completed:learning.completed,notes:learning.notes,updated_at:new Date().toISOString()};await check(await sb.from('pf_learning').upsert(payload));}
async function favorite(id){if(!user)return auth();const prev=[...learning.favorites];learning.favorites=prev.includes(id)?prev.filter(x=>x!==id):[...prev,id];try{await saveLearning();toast(learning.favorites.includes(id)?'Adicionado à sua lista.':'Removido da sua lista.');route(page)}catch(e){learning.favorites=prev;fail(e)}}
async function details(id){const c=courses.find(c=>c.id===id);if(!c)return;let lessons=[];if(access(c)&&c.status==='available')lessons=await check(await sb.from('pf_lessons').select('*').eq('course_id',id).order('sort_order'));modal(`<img class="modal-detail-image" src="${imageSrc(c.image)}" alt="" ${String(c.image).endsWith("-capa.png")?'style="object-fit:contain;background:#101111"':''}><span class="eyebrow">PRATFLIX ORIGINAL · ${E(c.area)}</span><h2>${E(c.title)}</h2><p>${E(c.subtitle)}</p><div class="detail-meta"><span class="pill ${c.access==='premium'?'gold':''}">${c.access==='free'?'GRATUITO':'PREMIUM'}</span><span class="mini-label">${E(c.level)}</span>${lessons.length?`<span class="mini-label">${lessons.length} conteúdos · ${lessons.reduce((a,l)=>a+l.minutes,0)} min</span>`:''}</div>${c.status==='soon'?`<div class="notice">Esta série faz parte da programação prevista para o lançamento. As aulas ainda estão em preparação.</div>${btn('Quero saber do lançamento','waitlist','spark')}`:!user?`${btn('Entrar e começar gratuitamente','auth','play')}<p>Seu progresso fica salvo na sua conta.</p>`:!access(c)?`<div class="notice">${tier()==='blocked'?'Seu acesso está suspenso. Entre em contato com a equipe.':'Este conteúdo faz parte do Premium.'}</div>${btn('Conhecer o Premium','premium','lock')}`:lessons.length?`<div>${lessons.map((l,i)=>`<button class="lesson-row" data-lesson="${l.id}" data-course-id="${c.id}"><span>${learning.completed.includes(l.id)?I('check'):String(i+1).padStart(2,'0')}</span><strong>${E(l.title)}</strong><small>${l.kind==='video'?'Vídeo':'Leitura'} · ${l.minutes} min</small>${I('arrow')}</button>`).join('')}</div>`:'<div class="notice">Os conteúdos desta série estão sendo preparados.</div>'}`)}
function safeURL(v){try{const u=new URL(v);return u.protocol==='https:'?u.href:''}catch{return ''}}
function videoEmbed(v){const spec=videoSpec(v);return spec&&spec.provider!=='mp4'?spec.src:'';}
async function openLesson(id,courseId){toolkit.cancel();journey.cancel();communityRequest++;const navigation=++navigationSeq;await stopVideoTracking();if(navigation!==navigationSeq)return;if(!user)return auth();const l=await check(await sb.from('pf_lessons').select('*').eq('id',id).maybeSingle());if(navigation!==navigationSeq)return;if(!l){toast('Conteúdo indisponível para este acesso.');return}if(preview){const c=courses.find(c=>c.id===l.course_id);if(c?.access!=='free'){toast('Este conteúdo não faz parte do acesso gratuito.');return}}courseLessons=await check(await sb.from('pf_lessons').select('*').eq('course_id',l.course_id).order('sort_order'));if(navigation!==navigationSeq)return;const remote=await sb.from('pf_playback').select('*').eq('user_id',user.id).eq('lesson_id',l.id).maybeSingle();if(navigation!==navigationSeq)return;const local=playbackRows.find(r=>r.lesson_id===l.id);if(remote.data&&(!local||Date.parse(remote.data.updated_at)>Date.parse(local.updated_at)))playbackRows=[remote.data,...playbackRows.filter(r=>r.lesson_id!==l.id)];playbackLessons=[...playbackLessons.filter(x=>x.course_id!==l.course_id),...courseLessons];lessonCurrent=l;close();page='lesson';history.replaceState(null,'','#lesson/'+id);const course=courses.find(c=>c.id===l.course_id);const ix=courseLessons.findIndex(x=>x.id===l.id),done=learning.completed.includes(id);shell(`${title('SUA SALA DE AULA',E(l.title),E(course?.title||'Conteúdo PratFlix'))}<div class="lesson-layout"><div>${l.kind==='video'?videoMarkup(l,playbackRows.find(r=>r.lesson_id===l.id)):''}<div class="panel">${renderReading(l.body)}</div><div class="buttons"><button class="btn" data-complete="${id}">${I(done?'check':'target')}${done?'Marcar como não concluído':'Concluir este conteúdo'}</button>${ix<courseLessons.length-1?`<button class="btn secondary" data-lesson="${courseLessons[ix+1].id}">Próximo conteúdo ${I('arrow')}</button>`:''}</div><div id="next-step" class="next-step" aria-live="polite"></div><div class="panel"><h2>O que você leva para a prática?</h2><p>Registre suas ideias. Estas anotações são privadas. Use apenas situações fictícias, sem dados de clientes.</p><textarea id="lesson-note" aria-label="Minha anotação" placeholder="Uma ideia, um próximo passo, uma dúvida..." style="margin-top:16px">${E(learning.notes[id]||'')}</textarea><button class="btn small" data-action="save-note" style="margin-top:12px">Salvar anotação</button></div><div class="panel"><h2>Conversa sobre o conteúdo</h2><p>Compartilhe uma dúvida ou reflexão. Os comentários passam pela aprovação da equipe.</p><form id="comment-form"><textarea name="body" required minlength="2" maxlength="3000" placeholder="Escreva sem incluir informações de clientes." aria-label="Comentário" style="margin:15px 0"></textarea><button class="btn small">Enviar para aprovação</button></form><div id="comments"></div></div></div><aside class="lesson-nav" style="width:auto;inset:auto;display:block;z-index:1"><h3>${E(course?.title)}</h3>${courseLessons.map((x,i)=>`<button class="lesson-row ${x.id===id?'selected':''}" data-lesson="${x.id}"><span>${learning.completed.includes(x.id)?I('check'):String(i+1).padStart(2,'0')}</span><strong>${E(x.title)}</strong></button>`).join('')}<div class="progress-line"><i style="width:${Math.round(courseLessons.filter(x=>learning.completed.includes(x.id)).length/courseLessons.length*100)}%"></i></div><p class="tagline">${courseLessons.filter(x=>learning.completed.includes(x.id)).length} de ${courseLessons.length} concluídos</p></aside></div>`);window.scrollTo(0,0);const touched=touchLesson(l);if(l.kind==='video')startVideoTracking(l);await touched;if(navigation!==navigationSeq||page!=='lesson')return;await loadComments()}
async function loadComments(){if(!lessonCurrent||!$('#comments'))return;const rows=await check(await sb.from('pf_comments').select('*').eq('course_id',lessonCurrent.course_id).order('created_at',{ascending:false}));if(!$('#comments'))return;$('#comments').innerHTML=rows.map(c=>`<article class="comment"><strong>${E(c.author)}</strong><small>${c.approved?'Publicado':'Aguardando aprovação'}</small><p>${E(c.body)}</p></article>`).join('')}
function resource(id){pratica.openResource(id)}
function downloadText(filename,text,type='text/plain;charset=utf-8'){const b=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const confirmationAttempts=new Map();
function confirmationForm(email='',expired=false){modal(`${brand}<span class="eyebrow">ACESSO À SUA CONTA</span><h2>${expired?'Vamos renovar seu link?':'Confirme seu e-mail.'}</h2><p>${expired?'Este link expirou, já foi utilizado ou não pôde ser validado. Solicite uma nova confirmação abaixo. Se você já confirmou sua conta, basta entrar.':'Abra a mensagem do PratFlix e clique em Confirmar meu cadastro. Confira também as pastas Spam e Promoções.'}</p><form id="confirmation-form"><label class="field">E-mail do cadastro<input name="email" type="email" required autocomplete="email" value="${E(email)}" placeholder="voce@exemplo.com"></label><div class="error" role="alert"></div><p id="confirmation-status" role="status" class="hint"></p><button class="btn full" type="submit">Reenviar confirmação ${I('arrow')}</button></form><p class="hint">Use sempre o e-mail mais recente. Aguarde pelo menos um minuto entre os pedidos.</p><button class="text-link" data-auth-mode="login">Já confirmei. Quero entrar</button><button class="text-link" data-auth-mode="reset" style="display:block;margin-top:16px">Preciso recuperar minha senha</button>`)}
function auth(mode='login'){if(mode==='resend')return confirmationForm();modal(`${brand}<h2>${mode==='signup'?'Sua prática começa aqui.':mode==='reset'?'Recupere seu acesso.':'Bom ter você de volta.'}</h2><p>${mode==='signup'?'Crie uma conta gratuita. Comece pelos conteúdos selecionados e acompanhe o lançamento.':mode==='reset'?'Informe o e-mail da sua conta para receber as instruções.':'Entre para continuar sua jornada no PratFlix.'}</p><div class="auth-tabs"><button class="${mode==='login'?'active':''}" data-auth-mode="login">Entrar</button><button class="${mode==='signup'?'active':''}" data-auth-mode="signup">Criar conta gratuita</button></div><form id="auth-form" class="auth-form" data-mode="${mode}">${mode==='signup'?'<label class="field">Seu nome<input name="name" required maxlength="100" autocomplete="name" placeholder="Como podemos chamar você?"></label>':''}<label class="field">E-mail<input type="email" name="email" required autocomplete="email" placeholder="voce@exemplo.com"></label>${mode!=='reset'?'<label class="field">Senha<input type="password" name="password" required minlength="8" autocomplete="'+(mode==='signup'?'new-password':'current-password')+'" placeholder="Pelo menos 8 caracteres"></label>':''}${mode==='signup'?`<label class="field">Sua área de interesse<select name="interest">${['Primeiros passos','Civil','Penal','Trabalho','Constitucional','Audiências','Gestão'].map(a=>`<option>${a}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="marketing">Quero receber dicas e novidades do lançamento. Posso retirar essa preferência depois.</label><p class="hint" style="margin:0">Usaremos seu e-mail para acesso à conta. Conheça a <button type="button" class="text-link" data-action="privacy" style="display:inline">política de privacidade</button>.</p>`:''}<div class="error" id="auth-error" role="alert"></div><button class="btn full">${mode==='signup'?'Criar minha conta gratuita':mode==='reset'?'Solicitar recuperação':'Entrar no PratFlix'} ${I('arrow')}</button></form>${mode==='login'?'<button class="text-link" data-auth-mode="reset" style="margin-top:18px">Esqueci minha senha</button><button class="text-link" data-auth-mode="resend" style="display:block;margin-top:12px">Não recebi a confirmação</button>':''}`)}
function passwordModal(){modal(`<span class="eyebrow">SEGURANÇA DA CONTA</span><h2>Defina sua nova senha</h2><form id="password-form"><label class="field">Nova senha<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><div class="error" id="password-error"></div><button class="btn" style="margin-top:20px">Salvar nova senha</button></form>`)}
async function waitlist(){if(preview){toast('Prévia: nenhum interesse será registrado.');return;}if(!user){auth('signup');return}if(tier()==='blocked'){toast('Seu acesso está suspenso.');return}const existing=await check(await sb.from('pf_waitlist').select('user_id').eq('user_id',user.id));if(!existing.length)await check(await sb.from('pf_waitlist').insert({user_id:user.id}));modal(`<span class="eyebrow">VOCÊ FAZ PARTE DO COMEÇO</span><h2>Interesse registrado, ${E(name())}.</h2><p>Sua conta está na lista de interessados no lançamento do PratFlix. Enquanto preparamos o Premium, aproveite os conteúdos gratuitos.</p>${btn('Continuar aprendendo','free-catalog','play')}`)}
async function loadAdmin(){if(!canAdmin())return;const seq=++routeSeq;shell(title('CENTRAL DE CONTROLE','Administração','Carregando os dados do PratFlix...'));try{const [m,c,w]=await Promise.all([sb.from('pf_members').select('*').order('created_at',{ascending:false}),sb.from('pf_comments').select('*').order('created_at',{ascending:false}),sb.from('pf_waitlist').select('*')]);adminData={members:await check(m),comments:await check(c),waitlist:await check(w)};if(seq!==routeSeq||page!=='admin')return;renderAdmin()}catch(e){fail(e)}}
function renderAdmin(){let content='';const m=adminData.members||[],free=m.filter(x=>x.tier==='free').length,premium=m.filter(x=>x.tier==='premium').length,blocked=m.filter(x=>x.tier==='blocked').length;const bars=(items)=>`<div class="bar-chart">${items.map(([n,v])=>`<div><span>${E(n)}</span><div class="bar"><i style="width:${Math.max(0,v/(m.length||1)*100)}%"></i></div><span>${v}</span></div>`).join('')}</div>`;if(adminTab==='Visão geral')content=`<div class="stats"><div class="stat"><label>Total de membros</label><strong>${m.length}</strong><small>Cadastros reais</small></div><div class="stat"><label>Acesso gratuito</label><strong>${free}</strong><small>Base de relacionamento</small></div><div class="stat"><label>Acesso Premium</label><strong>${premium}</strong><small>Acessos liberados</small></div><div class="stat"><label>Interesse no lançamento</label><strong>${adminData.waitlist.length}</strong><small>Inscrições confirmadas na plataforma</small></div></div><div class="read-grid"><div class="panel"><h2>Membros por acesso</h2>${bars([['Gratuito',free],['Premium',premium],['Suspenso',blocked]])}</div><div class="panel"><h2>Interesses da comunidade</h2>${bars([...new Set(m.map(x=>x.interest))].map(a=>[a,m.filter(x=>x.interest===a).length]))}</div></div><div class="panel"><h2>Preparação para o lançamento</h2><div class="resource-row"><span class="resource-icon">${I('users')}</span><div><h3>${m.filter(x=>x.marketing).length} membros autorizaram novidades</h3><p>O cadastro manual não pressupõe autorização de marketing.</p></div></div><div class="resource-row"><span class="resource-icon">${I('play')}</span><div><h3>${courses.filter(x=>x.status==='available').length} séries disponíveis · ${courses.filter(x=>x.status==='soon').length} em preparação</h3><p>Cadastre vídeos e publique novas séries na aba Conteúdos.</p></div></div><div class="resource-row"><span class="resource-icon">${I('message')}</span><div><h3>${adminData.comments.filter(x=>!x.approved).length} comentários aguardando aprovação</h3><p>Gerencie a conversa na aba Moderação.</p></div></div></div>`;
if(adminTab==='Divulgar')content=`<div class="panel"><span class="eyebrow">CONVITE PARA A VERSÃO GRATUITA</span><h2>Uma página pronta para compartilhar.</h2><p>Apresentação do PratFlix, recursos gratuitos e botões para criar conta ou entrar. Compartilhe este endereço no WhatsApp e nas redes.</p><label class="field">Link público<input readonly value="https://liberofilho.com/pratflix/" onclick="this.select()"></label><div class="buttons"><a class="btn" href="/pratflix/" target="_blank" rel="noopener">Ver página de inscrição ↗</a><button class="btn secondary" type="button" data-copy-invite>Copiar link</button></div><p id="invite-copy-status" role="status"></p></div>`;
if(adminTab==='Membros')content=`<div class="toolbar"><input id="member-search" placeholder="Buscar por nome ou e-mail" aria-label="Buscar membros"><select id="member-tier" aria-label="Filtrar acesso"><option value="all">Todos os acessos</option value="free">Gratuitos</option><option value="premium">Premium</option><option value="blocked">Suspensos</option></select><button class="btn" data-action="new-member">${I('plus')}Cadastrar pessoa</button><button class="btn secondary" data-action="import-members">Importar CSV</button><button class="btn secondary" data-action="export-members">Exportar CSV</button></div><div class="notice">Cadastrar uma pessoa libera o acesso para o e-mail informado. Ela entra com sua conta existente ou cria a própria senha no PratFlix. Nenhuma mensagem é enviada automaticamente por este cadastro.</div><div class="panel table-wrap"><table><thead><tr><th>Membro</th><th>Interesse</th><th>Acesso</th><th>Novidades</th><th>Origem</th><th></th></tr></thead><tbody id="members-body">${memberRows(m)}</tbody></table></div>`;
if(adminTab==='Conteúdos')content=`<div class="toolbar"><p class="tagline">Catálogo, leituras e vídeos</p><button class="btn" data-action="new-course">${I('plus')}Nova série</button></div><div class="panel table-wrap"><table><thead><tr><th>Série</th><th>Área</th><th>Acesso</th><th>Publicação</th><th>Ações</th></tr></thead><tbody>${courses.map(c=>`<tr><td>${E(c.title)}</td><td>${E(c.area)}</td><td>${c.access==='free'?'Gratuito':'Premium'}</td><td>${({available:'Disponível',soon:'Em breve',draft:'Rascunho'})[c.status]}</td><td><button class="btn small secondary" data-edit-course="${c.id}">Editar</button> <button class="btn small" data-manage-lessons="${c.id}">Aulas</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Para vídeos, use links do YouTube, Vimeo ou arquivos MP4 hospedados. Séries em rascunho ficam invisíveis para visitantes. O estado “Em breve” mostra a capa, sem liberar as aulas.</div>`;
if(adminTab==='Biblioteca')content=`<div class="toolbar"><p class="tagline">Materiais e arquivos de apoio</p><button class="btn" data-action="new-resource">${I('plus')}Novo material</button></div><div class="read-grid">${resources.map(r=>`<div class="tip-card"><span class="pill">${r.access==='free'?'GRATUITO':'PREMIUM'}</span><h3>${E(r.title)}</h3><p>${E(r.area)} · ${E(r.kind)}</p><button class="text-link" data-edit-resource="${r.id}">Editar material ${I('edit')}</button></div>`).join('')}</div>`;
if(adminTab==='Dicas')content=`<div class="toolbar"><p class="tagline">Conteúdo aberto para relacionamento</p><button class="btn" data-action="new-tip">${I('plus')}Nova dica</button></div><div class="read-grid">${tips.map(t=>`<div class="tip-card"><span class="eyebrow">${E(t.area)}</span><h3>${E(t.title)}</h3><p>${E(t.body)}</p><button class="text-link" data-edit-tip="${t.id}">Editar dica ${I('edit')}</button></div>`).join('')}</div>`;
if(adminTab==='Moderação')content=`<div class="panel"><h2>Comunidade</h2><p>Modere as publicações e respostas diretamente no mural da comunidade.</p><button class="text-link" data-action="community">Abrir comunidade ${I('arrow')}</button></div><div class="panel"><h2>Comentários da comunidade</h2>${adminData.comments.map(c=>`<article class="comment"><strong>${E(c.author)}</strong><small>${c.approved?'Publicado':'Aguardando aprovação'}</small><p>${E(c.body)}</p><small>${E(courses.find(x=>x.id===c.course_id)?.title||'Série')}</small><div style="margin-top:12px"><button class="btn small ${c.approved?'secondary':''}" data-moderate="${c.id}" data-approved="${c.approved?'false':'true'}">${c.approved?'Retirar da publicação':'Aprovar comentário'}</button></div></article>`).join('')||'<p>Nenhum comentário recebido por enquanto.</p>'}</div>`;
shell(title('CENTRAL DE CONTROLE','O PratFlix, nas suas mãos.','Gerencie conteúdos, acessos e o relacionamento com seus futuros assinantes.')+`<section class="admin-free-panel"><div><span class="eyebrow">EXPERIÊNCIA DO ALUNO</span><h2>Veja exatamente a área gratuita.</h2><p>Navegue sem trocar de conta e sem gravar respostas ou progresso.</p></div><div class="buttons">${btn('Ver versão gratuita','preview','eye')}${btn('Gerenciar recursos gratuitos','tools-admin','book',true)}<a class="btn secondary" href="#journey-admin">Cronograma, vídeo e grupo</a></div></section><div class="areas">${['Visão geral','Divulgar','Membros','Conteúdos','Biblioteca','Dicas','Moderação'].map(a=>`<button class="chip ${adminTab===a?'active':''}" data-admin-tab="${a}">${a}</button>`).join('')}</div>${content}`)}
function memberRows(rows){return rows.map(m=>`<tr><td>${E(m.name)}<small>${E(m.email)}</small></td><td>${E(m.interest)}</td><td><span class="pill ${m.tier==='premium'?'gold':''}">${({free:'Gratuito',premium:'Premium',blocked:'Suspenso'})[m.tier]}</span></td><td>${m.marketing?'Autorizou':'Não autorizou'}</td><td>${E(m.source)}</td><td><button class="btn small secondary" data-edit-member="${E(m.email)}">Gerenciar</button></td></tr>`).join('')||'<tr><td colspan="6">Nenhum membro encontrado.</td></tr>'}
const options=(values,current)=>values.map(x=>`<option value="${E(Array.isArray(x)?x[0]:x)}" ${(Array.isArray(x)?x[0]:x)===current?'selected':''}>${E(Array.isArray(x)?x[1]:x)}</option>`).join('');
function memberForm(email=''){const m=adminData.members?.find(x=>x.email===email)||{};modal(`<span class="eyebrow">MEMBROS E ACESSOS</span><h2>${email?'Gerenciar acesso':'Cadastrar uma pessoa'}</h2><form id="member-form" data-email="${E(email)}"><div class="form-grid"><label class="field wide">Nome<input name="name" value="${E(m.name)}" required maxlength="100"></label><label class="field wide">E-mail<input name="email" type="email" value="${E(m.email)}" required ${email?'readonly':''}></label><label class="field">Acesso<select name="tier">${options([['free','Gratuito'],['premium','Premium'],['blocked','Suspenso']],m.tier||'free')}</select></label><label class="field">Área de interesse<select name="interest">${options(['Primeiros passos','Civil','Penal','Trabalho','Constitucional','Audiências','Gestão'],m.interest||'Primeiros passos')}</select></label><label class="field">Telefone opcional<input name="phone" value="${E(m.phone)}" maxlength="30"></label><label class="field">Origem<input name="source" value="${E(m.source||'Cadastro manual')}" maxlength="100"></label></div><label class="check"><input type="checkbox" name="marketing" ${m.marketing?'checked':''}>A pessoa autorizou receber dicas e novidades.</label><p class="hint">O acesso é associado ao e-mail. A pessoa define a própria senha ao se cadastrar. Não haverá envio automático de mensagem.</p><div class="error" id="form-error"></div><button class="btn full">Salvar acesso</button></form>`)}
function courseForm(id=''){const c=courses.find(x=>x.id===id)||{};modal(`<span class="eyebrow">CATÁLOGO PRATFLIX</span><h2>${id?'Editar série':'Nova série'}</h2><form id="course-form" data-id="${id}"><div class="form-grid"><label class="field wide">Título<input name="title" required maxlength="180" value="${E(c.title)}"></label><label class="field wide">Descrição<textarea name="subtitle" maxlength="800">${E(c.subtitle)}</textarea></label><label class="field">Área<select name="area">${options([...new Set(['Primeiros passos','Civil','Penal','Trabalho','Constitucional','Audiências','Gestão',...courses.map(x=>x.area)])],c.area)}</select></label><label class="field">Nível<select name="level">${options(['Essencial','Intermediário','Avançado'],c.level)}</select></label><label class="field">Acesso<select name="access">${options([['free','Gratuito'],['premium','Premium']],c.access||'premium')}</select></label><label class="field">Status<select name="status">${options([['draft','Rascunho'],['soon','Em breve'],['available','Disponível']],c.status||'draft')}</select></label><label class="field">Imagem da capa<select name="image">${options([...(String(c.image||'').startsWith('https://convites.liberofilho.com/')?[[c.image,'Foto do professor']]:[]),['office','Escritório'],['desk','Mesa de trabalho'],['justice','Justiça'],['library','Biblioteca'],['meeting','Reunião'],['building','Arquitetura']],c.image||'desk')}</select></label><label class="field">Ordem no catálogo<input name="sort_order" type="number" value="${c.sort_order??courses.length+1}" min="0" max="10000"></label></div><label class="check"><input name="featured" type="checkbox" ${c.featured?'checked':''}>Usar como conteúdo inicial destacado</label><div class="error" id="form-error"></div><button class="btn full">Salvar série</button></form>`,true)}
async function manageLessons(id){const c=courses.find(x=>x.id===id);const list=await check(await sb.from('pf_lessons').select('*').eq('course_id',id).order('sort_order'));storeLessons=list;modal(`<span class="eyebrow">AULAS E LEITURAS</span><h2>${E(c?.title)}</h2><button class="btn" data-new-lesson="${id}">${I('plus')}Adicionar conteúdo</button><div style="margin-top:20px">${list.map(l=>`<div class="lesson-row"><span>${l.sort_order}</span><strong>${E(l.title)}</strong><small>${l.kind==='video'?'Vídeo':'Leitura'}</small><button class="btn small secondary" data-edit-lesson="${l.id}">Editar</button></div>`).join('')||'<p>Adicione o primeiro conteúdo desta série.</p>'}</div>`,true)}
let storeLessons=[];
function lessonForm(courseId,id=''){const l=storeLessons.find(x=>x.id===id)||{};modal(`<span class="eyebrow">SALA DE AULA</span><h2>${id?'Editar conteúdo':'Novo conteúdo'}</h2><form id="lesson-form" data-id="${id}" data-course="${courseId}"><div class="form-grid"><label class="field wide">Título<input name="title" required maxlength="180" value="${E(l.title)}"></label><label class="field">Formato<select name="kind">${options([['reading','Leitura'],['video','Vídeo']],l.kind||'reading')}</select></label><label class="field">Tempo estimado (minutos)<input name="minutes" type="number" required min="1" max="600" value="${l.minutes||5}"></label><label class="field wide">Link do vídeo<input name="video_url" type="url" value="${E(l.video_url)}" placeholder="https://www.youtube.com/watch?v=..."><small>YouTube, Vimeo ou arquivo MP4 em HTTPS. Necessário para o formato vídeo.</small></label><label class="field wide">Texto / material de apoio<textarea name="body" rows="12">${E(l.body)}</textarea></label><label class="field">Ordem na série<input name="sort_order" type="number" min="0" max="10000" value="${l.sort_order??storeLessons.length+1}"></label></div><div class="error" id="form-error"></div><button class="btn full">Salvar conteúdo</button></form>`,true)}
function resourceForm(id=''){const r=resources.find(x=>x.id===id)||{};modal(`<span class="eyebrow">BIBLIOTECA</span><h2>${id?'Editar material':'Novo material'}</h2><form id="resource-form" data-id="${id}"><div class="form-grid"><label class="field wide">Título<input name="title" required value="${E(r.title)}" maxlength="180"></label><label class="field">Tipo<select name="kind">${options(['Checklist','Modelo','Roteiro','Material complementar'],r.kind)}</select></label><label class="field">Área<input name="area" required value="${E(r.area||'Gestão')}" maxlength="100"></label><label class="field">Acesso<select name="access">${options([['free','Gratuito'],['premium','Premium']],r.access||'free')}</select></label><label class="field wide">Conteúdo<textarea name="body" rows="10">${E(r.body)}</textarea></label><label class="field wide">Link opcional para arquivo hospedado<input name="file_url" type="url" value="${E(r.file_url)}" placeholder="https://..."><small>Se informado, o botão baixar abre este arquivo. Sem link, o texto pode ser baixado ou salvo em PDF.</small></label></div><div class="error" id="form-error"></div><button class="btn full">Salvar material</button></form>`,true)}
function tipForm(id=''){const t=tips.find(x=>x.id===id)||{};modal(`<span class="eyebrow">DICAS GRATUITAS</span><h2>${id?'Editar dica':'Nova dica'}</h2><form id="tip-form" data-id="${id}"><div class="form-grid"><label class="field wide">Título<input name="title" required maxlength="180" value="${E(t.title)}"></label><label class="field wide">Categoria<input name="area" required value="${E(t.area||'Carreira')}" maxlength="100"></label><label class="field wide">Texto<textarea name="body" required rows="8">${E(t.body)}</textarea></label></div><div class="error" id="form-error"></div><button class="btn full">Publicar dica</button></form>`)}
function importModal(){modal(`<span class="eyebrow">SUA BASE GRATUITA</span><h2>Importar pessoas</h2><p>Use um arquivo CSV com cabeçalho: nome,email,interesse. A importação cria acessos gratuitos e preserva os cadastros existentes.</p><form id="import-form"><label class="field">Arquivo CSV<input name="csv" type="file" accept=".csv,text/csv" required></label><p class="hint">Máximo de 500 pessoas por arquivo. Nenhum e-mail será enviado. A autorização para marketing permanece desmarcada.</p><div class="error" id="form-error"></div><button class="btn full">Validar e importar</button></form><button class="text-link" data-action="csv-template" style="margin-top:18px">Baixar modelo CSV</button>`)}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const sep=text.split(/\r?\n/)[0].includes(';')?';':',';const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(q&&text[i+1]==='"'){cell+='"';i++}else q=!q}else if(ch===sep&&!q){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!q){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(c=>c.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(q)throw new Error('O CSV contém aspas não fechadas.');row.push(cell);if(row.some(c=>c.trim()))rows.push(row);return rows}
function csvVal(s){let t=String(s??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}
async function adminSave(form,table,payload){if(!canAdmin())throw Error('Acesso reservado à administração.');const id=form.dataset.id;await check(id?await sb.from(table).update(payload).eq('id',id):await sb.from(table).insert(payload));await data();close();toast('Alterações salvas.');renderAdmin()}
async function submit(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const fd=new FormData(f),val=k=>String(fd.get(k)||'').trim(),button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{if(f.id==='global-search'){query=val('search');area='Todas';route('catalog')}
if(f.id==='confirmation-form'){const email=val('email').toLowerCase(),remaining=60000-(Date.now()-(confirmationAttempts.get(email)||0));if(remaining>0)throw Error('Aguarde '+Math.ceil(remaining/1000)+' segundos para solicitar outro e-mail.');confirmationAttempts.set(email,Date.now());const r=await sb.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+'/pratflix/aulas.html'}});if(r.error)throw r.error;$('#confirmation-status').textContent='Se houver um cadastro aguardando confirmação, um novo e-mail será enviado. Confira sua caixa de entrada e use o link mais recente.';}
if(f.id==='auth-form'){const mode=f.dataset.mode;if(mode==='login'){const r=await sb.auth.signInWithPassword({email:val('email'),password:val('password')});if(r.error)throw r.error;await identity();await data();close();const dest=sessionStorage.getItem('pf.return')||'home';sessionStorage.removeItem('pf.return');route(dest);toast('Bem-vindo ao PratFlix.')}else if(mode==='signup'){const r=await sb.auth.signUp({email:val('email'),password:val('password'),options:{emailRedirectTo:location.origin+'/pratflix/aulas.html',data:{full_name:val('name'),pf_interest:val('interest'),pf_marketing:fd.has('marketing')}}});if(r.error)throw r.error;if(r.data.session){await identity();await data();close();const dest=sessionStorage.getItem('pf.return')||'welcome';sessionStorage.removeItem('pf.return');route(dest);toast('Sua conta gratuita está pronta.')}else{confirmationAttempts.set(val('email').toLowerCase(),Date.now());confirmationForm(val('email'))}}else{const r=await sb.auth.resetPasswordForEmail(val('email'),{redirectTo:location.origin+'/pratflix/aulas.html'});if(r.error)throw r.error;toast('Se houver uma conta, as instruções serão enviadas.')}}
if(f.id==='password-form'){const r=await sb.auth.updateUser({password:val('password')});if(r.error)throw r.error;close();toast('Senha atualizada.')}
if(f.id==='comment-form'){await check(await sb.from('pf_comments').insert({user_id:user.id,course_id:lessonCurrent.course_id,author:member?.name||name(),body:val('body'),approved:false}));f.reset();toast('Comentário enviado para aprovação.');await loadComments()}
if(f.id==='member-form'){if(!canAdmin())throw Error('Acesso restrito');const payload={name:val('name'),email:val('email').toLowerCase(),tier:val('tier'),interest:val('interest'),phone:val('phone'),source:val('source'),marketing:fd.has('marketing')};await check(f.dataset.email?await sb.from('pf_members').update(payload).eq('email',f.dataset.email):await sb.from('pf_members').insert(payload));close();toast('Acesso salvo.');await loadAdmin()}
if(f.id==='course-form'){await adminSave(f,'pf_courses',{title:val('title'),subtitle:val('subtitle'),area:val('area'),level:val('level'),access:val('access'),status:val('status'),image:val('image'),sort_order:Number(val('sort_order')),featured:fd.has('featured')})}
if(f.id==='lesson-form'){if(!canAdmin())throw Error('Acesso restrito');const url=val('video_url');if(val('kind')==='video'&&!videoSpec(url))throw Error('Informe um link válido do YouTube, Vimeo ou MP4 em HTTPS.');if(val('kind')==='reading'&&!val('body'))throw Error('Adicione o texto da leitura.');const payload={title:val('title'),body:val('body'),kind:val('kind'),video_url:url,minutes:Number(val('minutes')),sort_order:Number(val('sort_order')),course_id:f.dataset.course};await check(f.dataset.id?await sb.from('pf_lessons').update(payload).eq('id',f.dataset.id):await sb.from('pf_lessons').insert(payload));toast('Conteúdo salvo.');await manageLessons(f.dataset.course)}
if(f.id==='resource-form'){if(!val('body')&&!safeURL(val('file_url')))throw Error('Adicione um texto ou link de arquivo.');if(val('file_url')&&!safeURL(val('file_url')))throw Error('Use um link HTTPS válido.');await adminSave(f,'pf_resources',{title:val('title'),kind:val('kind'),area:val('area'),access:val('access'),body:val('body'),file_url:val('file_url')})}
if(f.id==='tip-form')await adminSave(f,'pf_tips',{title:val('title'),body:val('body'),area:val('area')});
if(f.id==='import-form'){if(!canAdmin())throw Error('Acesso restrito');const file=fd.get('csv');if(file.size>1e6)throw Error('Use um arquivo menor que 1 MB.');const rows=parseCSV(await file.text()),head=rows.shift().map(s=>s.trim().toLowerCase());const ni=head.indexOf('nome'),ei=head.indexOf('email'),ii=head.indexOf('interesse');if(ni<0||ei<0)throw Error('O cabeçalho precisa conter nome e email.');if(rows.length>500)throw Error('Limite de 500 pessoas por arquivo.');let errors=[],unique=new Map();rows.forEach((r,i)=>{const em=(r[ei]||'').trim().toLowerCase(),nm=(r[ni]||'').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(em)||!nm)errors.push(i+2);else unique.set(em,{email:em,name:nm.slice(0,100),interest:r[ii]?.trim()||'Primeiros passos',tier:'free',source:'Importação CSV',marketing:false})});if(errors.length)throw Error('Corrija nome ou e-mail nas linhas: '+errors.join(', '));const existing=new Set(adminData.members.map(m=>m.email));const batch=[...unique.values()].filter(x=>!existing.has(x.email));if(batch.length)await check(await sb.from('pf_members').insert(batch));close();toast(`${batch.length} pessoas cadastradas. ${unique.size-batch.length} cadastros existentes preservados.`);await loadAdmin()}
}catch(err){const el=f.querySelector('.error')||$('#form-error');let msg=err.message||'Não foi possível concluir.';if(/Invalid login credentials/i.test(msg))msg='E-mail ou senha incorretos.';if(/Email not confirmed/i.test(msg))msg='Confirme seu e-mail antes de entrar.';if(/duplicate key/i.test(msg))msg='Esse e-mail já está cadastrado. Use Gerenciar para alterar o acesso.';if(/rate limit/i.test(msg))msg='Limite de tentativas atingido. Aguarde alguns minutos e tente novamente.';if(el){el.textContent=msg;if(err.code==='email_not_confirmed'||/Email not confirmed/i.test(err.message||'')){const link=document.createElement('button');link.type='button';link.className='text-link';link.textContent='Reenviar confirmação';link.onclick=()=>confirmationForm(val('email'));el.append(document.createElement('br'),link);}}else fail(err)}finally{if(button)button.disabled=false}}
let playbackRows=[],playbackLessons=[],activePlayback=null,navigationSeq=0,playbackToken=null,playbackWriteChain=Promise.resolve();
const playbackStorage=()=>user?'pratflix.playback.pending.'+user.id:'';
function pendingPlayback(){try{return JSON.parse(localStorage.getItem(playbackStorage())||'{}')}catch{return {}}}
function rememberPlayback(row){if(!user||row.user_id!==user.id||preview)return;try{const pending=pendingPlayback();pending[row.lesson_id]=row;localStorage.setItem(playbackStorage(),JSON.stringify(pending))}catch{}}
function forgetPlayback(row){if(!user||row.user_id!==user.id)return;try{const pending=pendingPlayback();if(pending[row.lesson_id]?.updated_at===row.updated_at){delete pending[row.lesson_id];localStorage.setItem(playbackStorage(),JSON.stringify(pending))}}catch{}}
function playbackMessage(text,lessonId){if(page==='lesson'&&lessonCurrent?.id===lessonId&&$('#playback-status'))$('#playback-status').textContent=text;}
function cachePlayback(row){playbackRows=[row,...playbackRows.filter(x=>x.lesson_id!==row.lesson_id)];rememberPlayback(row);}
function persistPlayback(row){if(!user||preview||row.user_id!==user.id)return Promise.resolve();rememberPlayback(row);const write=async()=>{if(!user||row.user_id!==user.id)return;const response=await sb.from('pf_playback').upsert(row,{onConflict:'user_id,lesson_id'}).abortSignal(AbortSignal.timeout(7000));if(response.error)throw response.error;forgetPlayback(row);playbackMessage('Seu ponto está salvo na conta.',row.lesson_id);};playbackWriteChain=playbackWriteChain.catch(()=>{}).then(write);return playbackWriteChain.catch(()=>{playbackMessage('Sem sincronização no momento. Seu ponto foi guardado neste dispositivo para tentar novamente.',row.lesson_id);});}
async function loadPlaybackHistory(){if(!user){playbackRows=[];playbackLessons=[];return}try{let rows=await check(await sb.from('pf_playback').select('*').order('updated_at',{ascending:false}).limit(100));if(!preview){const pending=Object.values(pendingPlayback()).filter(r=>r.user_id===user.id&&r.lesson_id);for(const row of pending){let remote=rows.find(r=>r.lesson_id===row.lesson_id);if(!remote){const r=await sb.from('pf_playback').select('*').eq('lesson_id',row.lesson_id).eq('user_id',user.id).maybeSingle();if(r.error)continue;remote=r.data;}if(!remote||Date.parse(row.updated_at)>Date.parse(remote.updated_at)){await persistPlayback(row);rows=[row,...rows.filter(r=>r.lesson_id!==row.lesson_id)];}else forgetPlayback(row);}}playbackRows=rows;const ids=rows.map(r=>r.lesson_id);if(!ids.length){playbackLessons=[];return}const recent=await check(await sb.from('pf_lessons').select('id,course_id,title,kind,video_url,sort_order').in('id',ids));const courseIds=[...new Set(recent.map(l=>l.course_id))];playbackLessons=courseIds.length?await check(await sb.from('pf_lessons').select('id,course_id,title,kind,video_url,sort_order').in('course_id',courseIds).order('sort_order')):[];}catch(e){console.warn('Não foi possível carregar a retomada de aulas.');}}
function continueSection(){if(!user||tier()==='blocked')return '';const available=courses.filter(c=>access(c)&&c.status==='available');const items=continueItems(playbackRows,playbackLessons,available,learning.completed);if(!items.length)return `<section class="resume-intro"><span class="resource-icon">${I('play')}</span><div><strong>Continue de onde parou</strong><p>Ao começar uma aula, seu próximo passo aparecerá aqui. Nos vídeos, o ponto de reprodução fica salvo.</p></div><button class="text-link" data-action="catalog">Escolher uma aula ${I('arrow')}</button></section>`;return `<section class="section resume-section"><div class="section-head"><div><span class="eyebrow">SUA JORNADA CONTINUA</span><h2 style="margin-top:8px">Continue de onde parou</h2><p>Seu progresso acompanha você, também em outro dispositivo.</p></div><button class="text-link" data-action="progress">Meu progresso ${I('arrow')}</button></div><div class="resume-grid">${items.map(({course,lesson,progress,position,next,isNext,completedCount,total})=>`<article class="resume-card"><button class="resume-image" data-lesson="${lesson.id}" aria-label="Continuar ${E(lesson.title)}"><img src="${imageSrc(course.image)}" alt=""><span>${I('play')}</span></button><div class="resume-content"><span class="mini-label">${isNext?'SEU PRÓXIMO CONTEÚDO':lesson.kind==='video'?'CONTINUAR ASSISTINDO':'RETOMAR LEITURA'}</span><h3>${E(lesson.title)}</h3><p>${E(course.title)}</p>${lesson.kind==='video'&&position?`<div class="resume-time">${formatTime(position)}${progress?.duration_seconds?' de '+formatTime(progress.duration_seconds):''}</div><div class="progress-line"><i style="width:${progress?.duration_seconds?Math.min(100,position/progress.duration_seconds*100):0}%"></i></div>`:`<div class="resume-time">${completedCount} de ${total} conteúdos concluídos</div><div class="progress-line"><i style="width:${total?completedCount/total*100:0}%"></i></div>`}<button class="btn small" data-lesson="${lesson.id}">${I('play')}${isNext?'Começar próximo conteúdo':position?'Retomar em '+formatTime(position):lesson.kind==='video'?'Continuar aula':'Continuar leitura'}</button>${next?`<small class="resume-next">A seguir: ${E(next.title)}</small>`:''}</div></article>`).join('')}</div></section>`;}
function videoMarkup(lesson,row){const spec=videoSpec(lesson.video_url);if(!spec)return '<div class="notice">O vídeo ainda não foi vinculado. O conteúdo de apoio está abaixo.</div>';const pos=resumeSeconds(row,spec.key);let source=spec.src;if(spec.provider==='youtube'){const url=new URL(source);url.searchParams.set('enablejsapi','1');url.searchParams.set('origin',location.origin);url.searchParams.set('playsinline','1');url.searchParams.set('start',String(Math.floor(pos)));source=url.href;}if(spec.provider==='vimeo'){const url=new URL(source);url.searchParams.set('loop','0');url.searchParams.set('autoplay','0');source=url.href;}return `${spec.provider==='mp4'?`<video id="lesson-player" class="video" src="${E(source)}" controls playsinline preload="metadata" controlsList="nodownload"></video>`:`<iframe id="lesson-player" class="video" src="${E(source)}" title="${E(lesson.title)}" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>`}<div class="playback-bar"><span id="playback-status" role="status">${preview?'Prévia de aluno: o progresso não será alterado.':pos?'Retomada preparada em '+formatTime(pos)+'. Aperte play para continuar.':'Seu ponto será salvo automaticamente durante a aula.'}</span><button class="text-link" data-action="restart-video">${I('play')} Recomeçar vídeo</button></div>`;}
async function touchLesson(lesson){if(preview)return;let row=playbackRows.find(r=>r.lesson_id===lesson.id);const key=lessonKey(lesson);if(!row||row.video_key!==key)row={user_id:user.id,lesson_id:lesson.id,position_seconds:0,duration_seconds:0,video_key:key,finished:false};row={...row,updated_at:new Date().toISOString()};cachePlayback(row);await persistPlayback(row);}
