// Community: protected, moderated discussions shared by free and Premium members.
let communityCategory='Todas',communityView='recent',communitySearch='',communityPage=0,communityPosts=[],communityReplies=[],communityRequest=0;
const communityCategories=['Apresentações','Dúvidas práticas','Troca de experiências','Materiais e ideias','Conquistas','Avisos'];
const communityAllowed=()=>user&&(canAdmin()||member&&tier()!=='blocked');
const communityDate=s=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',timeZone:'America/Recife'}).format(new Date(s));
function communityIntro(){return title('CONEXÕES QUE VIRAM PRÁTICA','Sua advocacia também cresce na troca.','Um espaço para perguntar, compartilhar aprendizados e caminhar com quem também está construindo a própria prática.');}
function communityCard(p){return `<article class="discussion"><div class="discussion-head"><span class="avatar">${E(p.author.slice(0,2).toUpperCase())}</span><div><strong>${E(p.author)}</strong><small>${communityDate(p.created_at)}</small></div><span class="pill ${p.category==='Avisos'?'gold':''}">${E(p.category)}</span></div>${p.pinned?'<div class="eyebrow" style="margin-top:18px">FIXADO PELA EQUIPE</div>':''}<button class="discussion-title" data-thread="${p.id}">${E(p.title)}</button><p>${E(p.body.slice(0,260))}${p.body.length>260?'…':''}</p><div class="discussion-bottom"><button class="text-link" data-thread="${p.id}">${I('message')}Abrir conversa ${I('arrow')}</button>${p.status!=='approved'?`<span class="pill soon">${p.status==='hidden'?'Retirado pela moderação':'Aguardando aprovação'}</span>`:''}</div>${canAdmin()?`<div class="moderate-actions">${p.status!=='approved'?`<button class="btn small" data-community-moderate="${p.id}" data-table="pf_posts" data-status="approved">Aprovar</button>`:`<button class="btn small secondary" data-community-moderate="${p.id}" data-table="pf_posts" data-status="hidden">Ocultar</button>`}<button class="btn small secondary" data-community-pin="${p.id}">${p.pinned?'Desafixar':'Fixar no mural'}</button></div>`:''}</article>`;}
function communityShell(content){shell(communityIntro()+`<div class="community-layout"><div><div class="community-welcome"><span class="resource-icon">${I('users')}</span><div><span class="eyebrow">SEU PONTO DE ENCONTRO</span><h2>Você não precisa descobrir tudo sozinho.</h2><p>Compartilhe uma dúvida, conte uma experiência ou apresente-se. A comunidade está aberta aos membros gratuitos e Premium.</p></div></div><div class="community-toolbar"><button class="btn" data-community-new="true">${I('plus')}Começar uma conversa</button>${communityAllowed()?`<button class="chip ${communityView==='recent'?'active':''}" data-community-view="recent">Mural</button><button class="chip ${communityView==='mine'?'active':''}" data-community-view="mine">Minhas publicações</button>${canAdmin()?`<button class="chip ${communityView==='pending'?'active':''}" data-community-view="pending">${I('shield')} Moderação</button>`:''}`:''}</div><div class="areas">${['Todas',...communityCategories].map(c=>`<button class="chip ${communityCategory===c?'active':''}" data-community-category="${E(c)}">${E(c)}</button>`).join('')}</div>${communityAllowed()?`<form id="community-search" class="toolbar"><input name="query" placeholder="Buscar pelo título de uma conversa" aria-label="Buscar na comunidade" value="${E(communitySearch)}"><button class="btn secondary">${I('search')} Buscar</button></form>`:''}<div id="community-feed">${content}</div></div><div class="community-side"><section class="panel"><span class="eyebrow">COMECE POR AQUI</span><h2 style="margin-top:14px">O primeiro passo é um oi.</h2><p>Conte sua área de interesse e o que você quer desenvolver na advocacia.</p><button class="text-link" data-community-present="true">Me apresentar ${I('arrow')}</button></section><section class="panel"><span class="eyebrow">UMA BOA CONVERSA COMEÇA COM RESPEITO</span><div class="community-rule">${I('check')}Troque ideias com gentileza.</div><div class="community-rule">${I('lock')}Use casos fictícios, sem dados de clientes.</div><div class="community-rule">${I('shield')}Publicações e respostas passam por aprovação.</div><div class="community-rule">${I('book')}Discussões são educativas e não substituem a análise do caso concreto.</div></section><section class="panel"><span class="eyebrow">APRENDER E COMPARTILHAR</span><h2 style="margin-top:14px">Leve uma ideia para a prática.</h2><p>Comece pelos conteúdos gratuitos e traga seus aprendizados para a conversa.</p><button class="text-link" data-action="free-catalog">Explorar conteúdos ${I('arrow')}</button></section></div></div>`);}
async function loadCommunity(){const request=++communityRequest;page='community';if(!communityAllowed()){communityShell(empty(user?'Acesso suspenso':'Entre na conversa',user?'Seu acesso à comunidade está suspenso. Entre em contato com a equipe.':'Crie uma conta gratuita para ler as conversas, publicar dúvidas e compartilhar experiências.',user?'account':'signup',user?'Minha conta':'Criar conta gratuita'));return;}communityShell('<div class="notice" role="status">Carregando as conversas...</div>');try{let q=sb.from('pf_posts').select('*').order('pinned',{ascending:false}).order('created_at',{ascending:false}).range(communityPage*20,communityPage*20+19);if(communityCategory!=='Todas')q=q.eq('category',communityCategory);if(communityView==='mine')q=q.eq('user_id',user.id);else q=q.eq('status',communityView==='pending'&&canAdmin()?'pending':'approved');if(communitySearch)q=q.ilike('title','%'+communitySearch.replace(/[%_]/g,'')+'%');const posts=await check(await q);let replies=[];if(canAdmin()&&communityView==='pending')replies=await check(await sb.from('pf_replies').select('*').eq('status','pending').order('created_at').limit(50));if(request!==communityRequest||page!=='community')return;communityPosts=posts;communityReplies=replies;let html=posts.length?posts.map(communityCard).join(''):empty(communityView==='pending'?'Nenhuma publicação pendente':communityView==='mine'?'Sua primeira conversa começa aqui':'Vamos começar essa conversa?',communitySearch?'Nenhuma conversa corresponde a essa busca.':communityView==='pending'?'As publicações enviadas pelos membros aparecerão aqui.':'Uma dúvida ou experiência pode ser o começo de uma boa troca.','','');if(replies.length)html+='<div class="panel"><h2>Respostas aguardando aprovação</h2>'+replies.map(r=>`<article class="comment"><strong>${E(r.author)}</strong><p>${E(r.body)}</p><div class="moderate-actions"><button class="btn small" data-community-moderate="${r.id}" data-table="pf_replies" data-status="approved">Aprovar</button><button class="btn small secondary" data-community-moderate="${r.id}" data-table="pf_replies" data-status="hidden">Ocultar</button><button class="text-link" data-thread="${r.post_id}">Ver contexto ${I('arrow')}</button></div></article>`).join('')+'</div>';html+=`<div class="community-toolbar">${communityPage?'<button class="btn secondary" data-community-page="prev">Página anterior</button>':''}${posts.length===20?'<button class="btn secondary" data-community-page="next">Próxima página</button>':''}</div>`;$('#community-feed').innerHTML=html;}catch(e){if(page==='community')$('#community-feed').innerHTML='<div class="notice">Não foi possível carregar. <button class="text-link" data-action="community">Tentar novamente</button></div>';fail(e)}}
function communityCompose(category='Dúvidas práticas'){if(!user)return auth('signup');if(!communityAllowed()){toast('Seu acesso à comunidade está suspenso.');return}modal(`<span class="eyebrow">ESPAÇO PARA TROCAR</span><h2>Comece uma conversa.</h2><form id="community-post-form"><div class="form-grid"><label class="field wide">Categoria<select name="category">${options(communityCategories.filter(c=>canAdmin()||c!=='Avisos'),category)}</select></label><label class="field wide">Título<input name="title" required minlength="3" maxlength="180" placeholder="Qual é a sua dúvida ou ideia?"></label><label class="field wide">Sua publicação<textarea name="body" required minlength="10" maxlength="6000" rows="8" placeholder="Compartilhe o contexto sem incluir dados de clientes."></textarea></label></div><p class="hint">${canAdmin()?'Publicações da administração são publicadas diretamente.':'Sua publicação ficará visível após a aprovação da equipe.'}</p><div class="error" role="alert"></div><button class="btn full">${canAdmin()?'Publicar conversa':'Enviar para aprovação'}</button></form>`,true)}
async function communityThread(id){if(!communityAllowed())return auth();const p=await check(await sb.from('pf_posts').select('*').eq('id',id).maybeSingle());if(!p||preview&&p.status!=='approved'&&p.user_id!==user.id){toast('Esta conversa não está disponível.');return}let rows=await check(await sb.from('pf_replies').select('*').eq('post_id',id).order('created_at').limit(200));if(preview)rows=rows.filter(r=>r.status==='approved'||r.user_id===user.id);modal(`<span class="eyebrow">COMUNIDADE · ${E(p.category)}</span><h2>${E(p.title)}</h2><div class="discussion-head"><span class="avatar">${E(p.author.slice(0,2).toUpperCase())}</span><div><strong>${E(p.author)}</strong><small>${communityDate(p.created_at)}</small></div></div><div class="reading" style="margin:22px 0">${E(p.body)}</div>${p.status!=='approved'?'<div class="notice">Esta publicação ainda não está no mural público da comunidade.</div>':''}<div class="thread-replies"><h3>Respostas</h3>${rows.length?rows.map(r=>`<article class="comment"><strong>${E(r.author)}</strong><small>${communityDate(r.created_at)}${r.status!=='approved'?' · '+(r.status==='hidden'?'Oculta':'Aguardando aprovação'):''}</small><p>${E(r.body)}</p>${canAdmin()?`<button class="text-link" data-community-moderate="${r.id}" data-table="pf_replies" data-status="${r.status==='approved'?'hidden':'approved'}" data-return-thread="${id}">${r.status==='approved'?'Ocultar resposta':'Aprovar resposta'}</button>`:''}</article>`).join(''):'<p>Ainda não há respostas publicadas.</p>'}</div>${p.status==='approved'||canAdmin()?`<form id="community-reply-form" data-post="${id}"><label class="field">Sua contribuição<textarea name="body" required minlength="2" maxlength="3000" placeholder="Compartilhe seu ponto de vista com respeito."></textarea></label><p class="hint">${canAdmin()?'Sua resposta será publicada.':'Sua resposta será publicada após aprovação.'}</p><div class="error" role="alert"></div><button class="btn">${canAdmin()?'Publicar resposta':'Enviar resposta'}</button></form>`:''}`,true)}
actions.community=()=>route('community');
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.communityNew)communityCompose();if(b.dataset.communityPresent)communityCompose('Apresentações');if(b.dataset.communityCategory){communityCategory=b.dataset.communityCategory;communityPage=0;await loadCommunity()}if(b.dataset.communityView){communityView=b.dataset.communityView;communityPage=0;await loadCommunity()}if(b.dataset.communityPage){communityPage=Math.max(0,communityPage+(b.dataset.communityPage==='next'?1:-1));await loadCommunity()}if(b.dataset.thread)await communityThread(b.dataset.thread);if(b.dataset.communityModerate&&canAdmin()&&['pf_posts','pf_replies'].includes(b.dataset.table)&&['approved','hidden'].includes(b.dataset.status)){b.disabled=true;await check(await sb.from(b.dataset.table).update({status:b.dataset.status}).eq('id',b.dataset.communityModerate));toast('Moderação salva.');if(b.dataset.returnThread)await communityThread(b.dataset.returnThread);else await loadCommunity()}if(b.dataset.communityPin&&canAdmin()){const p=communityPosts.find(x=>x.id===b.dataset.communityPin);if(!p)return;await check(await sb.from('pf_posts').update({pinned:!p.pinned}).eq('id',p.id));await loadCommunity();toast(p.pinned?'Publicação desafixada.':'Publicação fixada.')}}catch(e){fail(e)}finally{b.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['community-post-form','community-reply-form','community-search'].includes(f.id))return;e.preventDefault();const fd=new FormData(f),button=f.querySelector('button');button.disabled=true;try{if(f.id==='community-search'){communitySearch=String(fd.get('query')||'').trim().slice(0,180);communityPage=0;await loadCommunity();return}if(!communityAllowed())throw Error('Entre com uma conta ativa para participar.');const payload={user_id:user.id,author:(member?.name||name()).slice(0,100),body:String(fd.get('body')||'').trim(),status:canAdmin()?'approved':'pending'};if(f.id==='community-post-form'){await check(await sb.from('pf_posts').insert({...payload,title:String(fd.get('title')||'').trim(),category:String(fd.get('category')),pinned:false}));close();communityView='mine';communityCategory='Todas';communitySearch='';communityPage=0;await loadCommunity();toast(canAdmin()?'Conversa publicada.':'Publicação enviada para aprovação.')}else{await check(await sb.from('pf_replies').insert({...payload,post_id:f.dataset.post}));await communityThread(f.dataset.post);toast(canAdmin()?'Resposta publicada.':'Resposta enviada para aprovação.')}}catch(e){const error=f.querySelector('.error');if(error)error.textContent=e.message||'Não foi possível enviar.';else fail(e)}finally{button.disabled=false}});

document.addEventListener('click',async e=>{if(!e.target.closest('[data-copy-invite]'))return;try{await navigator.clipboard.writeText('https://liberofilho.com/pratflix/');$('#invite-copy-status').textContent='Link copiado. Pronto para compartilhar.'}catch{$('#invite-copy-status').textContent='Selecione o endereço acima e copie o link.'}});
